{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The attached IAM policy may grant excessive privileges if it allows '*' actions on 'iam:*' resources."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy" {
  user       = aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}

data "aws_iam_policy_document" "privesc19-UpdateExistingGlueDevEndpoint" {
  statement {
    effect = "Allow"
    actions = [
      "glue:UpdateDevEndpoint",
    ]
    resources = [
      "arn:aws:glue:*:*:devEndpoint/*",
    ]
  }
}

resource "aws_iam_policy" "privesc19-UpdateExistingGlueDevEndpoint" {
  name        = "privesc19-UpdateExistingGlueDevEndpoint"
  description = "Policy for privesc19-UpdateExistingGlueDevEndpoint"
  policy      = data.aws_iam_policy_document.privesc19-UpdateExistingGlueDevEndpoint.json
}",
  "fix_summary": "Added a restricted IAM policy document and updated the IAM policy to use it, ensuring it does not allow full IAM privileges."
}
